class Solution {
  private static long product(int[] nums, int mask, long target) {
    long p = 1;
    for (int i = 0; i < nums.length; i++) {
      if ((mask >> i & 1) == 0) continue;
      if (p > target / nums[i]) return -1;
      p *= nums[i];
    }
    return p;
  }

  public boolean checkEqualPartitions(int[] nums, long target) {
    int n = nums.length, full = (1 << n) - 1;
    for (int mask = 1; mask < full; mask++) {
      if (product(nums, mask, target) == target && product(nums, full ^ mask, target) == target)
        return true;
    }
    return false;
  }
}
